-- Forums are hiring leads, not independently verified employer vacancies.
on conflict(slug) do update set provider=excluded.provider,board_key=excluded.board_key,careers_url=excluded.careers_url,source_kind=excluded.source_kind,segment=excluded.segment,segment_note=excluded.segment_note,verification_status=excluded.verification_status,verification_note=excluded.verification_note,source_verified_at=excluded.source_verified_at,next_check_at=now(),enabled=true;
